parameters.responseBody:
={{ JSON.stringify({
  answer: '',
  error: 'IncidentMind AI Agent failed to process the request.',
  memory_used: false,
  memories: [],
  sources: [],
  tools_used: [],
  conversation_id: $('Webhook').first().json.body.conversation_id ?? ''
}) }}

assignments.value:
={{ (() => {
  const raw = $json.output ?? '';
  const sessionId = $('Webhook').first().json.body.conversation_id ?? '';
  let parsed = null;
  try {
    const m = String(raw).match(/\{[\s\S]*\}/);
    if (m) parsed = JSON.parse(m[0]);
  } catch (e) {}
  const base = parsed && parsed.answer ? parsed : { answer: raw, memory_used: false, memories: [], sources: [], tools_used: [] };
  base.conversation_id = sessionId;
  return JSON.stringify(base);
})() }}
